result:
.menusCon{
	overflow: hidden;
}
.menus {
  display: flex;
  align-items: center;
  width: 10000%;
  height: 40px;
  cursor pointer;
  padding-left: 12px;

  .item {
    position: relative;
    color: #333;
	font-size: 14px;
	margin-right: 28px;
	z-index: 9;

	&.on{
		font-size: 16px;
		font-weight: 600;

		span {
		  display: block;
		  position: absolute;
		  left: 50%;
		  bottom: 4px;
		  width: 100%;
		  height: 4px;
		  border-radius: 100px;
		  transform: translateX(-50%);
		  background: #fff;
		  background: linear-gradient(90deg, #E93323 0%, #FF7931 100%);
		  z-index: -1;
		}
	}

	&.on2{
		width: 46px;
		height: 24px;
		text-align: center;
		line-height: 24px;
		color: #fff;
		background: linear-gradient(90deg, #E93323 0%, #FF7931 100%);
		border-radius: 50px;
	}

	&.on3{
		font-size: 16px;
		font-weight: 600;
		color: #E93323;

		span{
			position: absolute;
			width: 30px;
			height: 30px;
			border:3px solid #E93323
			border-left: 3px solid transparent !important;
			border-top: 3px solid transparent !important;
			border-right: 3px solid transparent !important;
			border-radius: 50%
			bottom: -4px;
			left: 50%;
			transform: translateX(-50%);
		}
	}
  }
}
